mapper.select:
select *
from b_marketing_transfer_sync_${cid}
where cust_num = #{caseNum}
order by create_time desc limit 1;

select * from b_marketing_transfer_sync_${cid}
where cust_num=#{caseNum} and api_code=#{apicode} and user_type=#{userType}

     and create_time<= #{timeAddHour} 

order by create_time desc limit 1;

select *
from b_marketing_transfer_sync_${tcId}
where api_code = #{apiCode}
  and cust_num = #{custNum}

  and user_type = #{userType}

order by create_time desc, id desc limit 1;

select * from b_marketing_transfer_sync_${cid}
where cust_num=#{caseNum}

     and create_time<= #{timeAddHour} 

order by create_time desc limit 1;

select * from
b_marketing_transfer_sync_${cid}
where request_data=#{data}
order by cust_num desc,insert_time desc,id desc
limit #{limitStart},#{pageSize};

select * from
b_marketing_transfer_sync_${cid}
where request_data=#{data} and api_code = #{apiCode}
order by id desc
limit #{limitStart},2000;

select * from
b_marketing_transfer_sync_${cid}
where
  request_data = #{endDate} 
order by create_time desc,id desc limit #{limitStart},2000;

select t2.* from b_marketing_transfer_sync_${transferSyncUser.tCid} t2,(select id from
b_marketing_transfer_sync_${transferSyncUser.tCid}
where

        api_code=#{transferSyncUser.apiCode}

     and request_data >= #{startDate}  and  request_data <= #{endDate} 
order by


        ${orderByClause}


        id


limit ${rowCount},${offset}
) as t1 where t1.id = t2.id

select * from b_marketing_transfer_sync_${tCid}
where

        api_code=#{apiCode}

     and request_data = #{requestDate} 
     and id >= #{beginId} and id < #{endId} 
order by id

SELECT max(id) as id FROM b_marketing_transfer_sync_${tCid} where
api_code=#{apiCode} and
request_data = #{requestDate}

SELECT min(id) as id FROM b_marketing_transfer_sync_${tCid} where
api_code=#{apiCode} and
request_data = #{requestDate}

select * from
    b_marketing_transfer_sync_${cid}
where
  request_data < #{endDate} 
and api_code = #{apiCode}

    and id > #{indexId}

order by id limit #{pageSize};

select sha256_code_list,result,org_channel,mkt_level
from b_xiecheng_sms_colliding_data_log_vt
where send_date = #{day}
order by id desc limit #{limitStart},2000;

select * from
    b_marketing_transfer_sync_${cid}
where
  request_data = #{endDate}  and api_code = #{apiCode}
order by id desc limit #{limitStart},2000;

SELECT b.cust_num, b.reserve_field1, b.request_time FROM ( SELECT cust_num, max( request_time ) AS request_time FROM b_marketing_transfer_sync_${cid} WHERE cust_num IN
#{custNumList}
and api_code = #{apiCode} GROUP BY cust_num ) AS a LEFT JOIN b_marketing_transfer_sync_${cid} b ON a.cust_num = b.cust_num AND a.request_time = b.request_time and b.api_code = #{apiCode}

select * from
    b_marketing_transfer_sync_${cid}
where api_code=#{apiCode}
and apply_result=1
  and apply_dt > #{startDay} and apply_dt < #{endDay} 
order by apply_dt desc,id desc limit #{limitStart},2000

select * from
b_marketing_transfer_sync_${tcId}
where api_code=#{apiCode} and case_effective ='0'
and cust_num in

    #{item}

select * from
b_marketing_transfer_sync_${tcId}
where api_code=#{apiCode} and
 request_data = #{eliminateDate} 
and reserve_field1 ->'$.applyLoan'='1';

select ts.id,ts.cust_num,ts.reserve_field1,ts.create_time,ts.user_type,ts.if_transform from  b_marketing_transfer_sync_${tcId} ts
where   ts.request_data = #{endDate}  and ts.api_code=#{apiCode}
order by ts.create_time desc,ts.id desc limit #{limitStart},2000

select b.* from ( select cust_num,max(insert_time) as insert_time from b_marketing_transfer_sync_${cid} a where cust_num in
#{custNum}
and request_data = #{date}
and (IFNULL(reserve_field1,'') ='' or reserve_field1 not like '%"transform":"1"%') group by cust_num ) as a left join b_marketing_transfer_sync_${cid} b on a.cust_num = b.cust_num and a.insert_time = b.insert_time

select b.* from
(
select cust_num,max(request_time) as request_time
from b_marketing_transfer_sync_${cid} a
where cust_num in

    #{custNum}


    and request_data = #{date}

group by cust_num
) as a
left join b_marketing_transfer_sync_${cid} b on a.cust_num = b.cust_num and a.request_time = b.request_time

select * from
b_marketing_transfer_sync_${tCid}


        AND api_code =#{apiCode}


        AND id >=#{minId}

     AND create_time >= #{startDate} and create_time < #{endDate} 
    order by id asc limit 2000;

select t2.* from b_marketing_transfer_sync_${transferSyncUser.tCid} t2,(select id from
b_marketing_transfer_sync_${transferSyncUser.tCid}


        AND api_code=#{transferSyncUser.apiCode}


        AND create_time between #{startTime} and #{endTime}


        AND if_login=#{transferSyncUser.ifLogin}


        AND if_apply=#{transferSyncUser.ifApply}


        AND apply_result=#{transferSyncUser.applyResult}


        AND if_lent=#{transferSyncUser.ifLent}


        AND request_data=#{transferSyncUser.requestData}


order by


        ${orderByClause}


        id


limit ${rowCount},${offset}
) as t1 where t1.id = t2.id

select *
from b_marketing_transfer_sync_${tcId}
where
  create_time >= #{startTime}
and create_time < #{endTime} 

    and api_code = #{apiCode}

order by create_time desc limit #{pageIndex},#{pageSize}

select cust_num, apply_result, apply_dt, type, create_time, reserve_field1,user_type,api_code
from b_marketing_transfer_sync_${tcId} t1,
(select id from b_marketing_transfer_sync_${tcId}
where apply_result = #{applyResult}

    and api_code = #{apiCode}

and  request_data=#{requestDate} and apply_dt<='${applyDt} 23:59:59' 
order by apply_dt desc, id desc limit #{rowCount}, #{offset}) as t2
where t1.id = t2.id

select cust_num from b_marketing_transfer_sync_${tcId}
where (case_effective=#{caseEffective}
or ( request_data=#{requestDate} and apply_dt>=#{applyDt} and apply_dt<='${requestDate} 23:59:59' 
and apply_result is not null and apply_result!=''))

    and api_code = #{apiCode}


    and cust_num in

        #{item}


group by cust_num

select * from
b_marketing_transfer_sync_${tCid}

    unlent_amount > '0.00'

        AND id >=#{minId}

    AND request_data = #{requestData}
    order by id asc limit 2000;

select * from
b_marketing_transfer_sync_${tCid}

    audit_amount > '0.00'

        AND id >=#{minId}

    AND request_data = #{requestData}
    AND  json_unquote(json_extract(reserve_field1,'$.applyLoan')) = '0'
    order by id asc limit 2000;

select * from
b_marketing_transfer_sync_${tCid}

    if_apply= '0'

        AND id >=#{minId}

    AND request_data = #{requestData}
    AND if_lent= '0'
    AND   register_time >= #{registerTime} and register_time < #{requestData} 
    AND  json_unquote(json_extract(reserve_field1,'$.applyLoan')) = '0'
    order by id asc limit 2000;

select * from
b_marketing_transfer_sync_${tCid}

    if_login= '1'

        AND id >=#{minId}

    AND request_data = #{requestData}
    AND if_apply= '0'
    AND if_lent= '0'
    AND   login_time >= #{loginTime} and login_time < #{requestData} 
    AND  json_unquote(json_extract(reserve_field1,'$.applyLoan')) = '0'
    order by id asc limit 2000;

select cust_num from
b_marketing_transfer_sync_${tCid}
where
cust_num in

    #{custNum}

AND unlent_amount= '0.00'
AND lent_time >= #{lentTime}

select cust_num from
b_marketing_transfer_sync_${tCid}
where
cust_num in

    #{custNum}

AND json_unquote(json_extract(reserve_field1,'$.applyLoan')) = '1'
AND json_unquote(json_extract(reserve_field1,'$.applyLoanTime'))>= #{applyLoanTime}

select cust_num from
b_marketing_transfer_sync_${tCid}
where
cust_num in

    #{custNum}

AND apply_dt >=#{applyDt}

select count(id) from
b_marketing_transfer_sync_${tcId}
where
api_code = #{apiCode}
AND request_data = #{requestData}

select *
from b_marketing_transfer_sync_${tcId}
where request_data = #{requestData}
  AND json_unquote(json_extract(reserve_field1, '$.convType')) = #{convType}
group by cust_num
order by id asc  limit #{limitStart}, 500

select cust_num
from b_marketing_transfer_sync_${tcId}
where request_data = #{requestData}
and cust_num in

    #{custNum}

  AND ${convTypeStr}

select *
from b_marketing_transfer_sync_${tcId}
where request_data = #{requestDate}
and user_type in

    #{userType}


    and reserve_field1->'$.ifActivity'=#{ifActivity}


    and replace(substring(reserve_field1->'$.activityTime',1,11),'"','')=#{activityTime}


    and if_apply=#{ifApply}


    and STR_TO_DATE(apply_dt,'%Y-%m-%d') = #{applyDt}


    and id > #{minId}

order by id asc
limit #{pageSize}

select *
from b_marketing_transfer_sync_${tcId}
where api_code = #{apiCode}
  and user_type in

    #{userType}


    and if_apply=#{ifApply}

 and register_time >= #{registerStartTime} and register_time < #{registerEndTime} 

    and id > #{minId}

order by id asc
limit #{pageSize}

select * from
b_marketing_transfer_sync_${tCid}

    api_code = #{apiCode}
    and request_data = DATE_FORMAT(now(),"%Y-%m-%d")
    and if_apply = '1'
    and (apply_result is null or apply_result ='')
    and  audit_amount >= 1000
    and  apply_dt between DATE_SUB(DATE_FORMAT(now(),"%Y-%m-%d"),INTERVAL 1 day) and DATE_FORMAT(now(),"%Y-%m-%d")

        AND id >=#{minId}

    order by id asc limit 2000;

SELECT a.* FROM b_marketing_transfer_sync_${tCid} a INNER JOIN b_phone_sale_extend_info b ON a.cust_num = b.cust_num WHERE a.api_code = #{apiCode} and b.status ="a" AND ( b.create_time BETWEEN DATE_SUB( date_format(now(),"%Y-%m-%d"), INTERVAL 2 DAY ) AND DATE_SUB(date_format(now(),"%Y-%m-%d"), INTERVAL 1 DAY ) OR b.create_time BETWEEN DATE_SUB(date_format(now(),"%Y-%m-%d"),INTERVAL 6 DAY ) AND DATE_SUB( date_format(now(),"%Y-%m-%d"), INTERVAL 5 DAY ) )
AND a.id >= #{minId}
ORDER BY a.id ASC LIMIT 2000;

select * from
b_marketing_transfer_sync_${tCid}

    api_code = #{apiCode}
    and
    request_data = DATE_FORMAT(now(),"%Y-%m-%d")
    and if_apply = '1'
    and (apply_result is null or apply_result ='')
    and  audit_amount >= 1000
    and  login_time between DATE_SUB(DATE_FORMAT(now(),"%Y-%m-%d"),INTERVAL 1 day) and DATE_FORMAT(now(),"%Y-%m-%d")

        AND id >=#{minId}

    order by id asc limit 2000;

select * from
b_marketing_transfer_sync_${tCid}

    api_code = #{apiCode}
    and
    request_data = DATE_FORMAT(now(),"%Y-%m-%d")
    and if_login = '1'
    and (if_apply is null or if_apply ='')
    and (apply_result is null or apply_result ='')
    and (if_lent is null or if_lent ='')

        AND id >=#{minId}

    order by id asc limit 2000;

select * from
b_marketing_transfer_sync_${tCid}
where api_code = #{apiCode}
  and cust_num =#{custNum} and audit_amount!=null and audit_amount!='' and lent_amount!=null and lent_amount!=''  and audit_amount-lent_amount <1000

select cust_num as custNum
       ,request_data as requestData
       ,request_time as requestTime
       ,reserve_field1 as reserveField1
from b_marketing_transfer_sync_${tcId}
where
      api_code = #{apiCode}
  and request_data >= #{requestDate}
  and cust_num in

    #{custNum}

select b.cust_num
from (select id from
    b_marketing_transfer_sync_${tCid}
where api_code = #{apiCode}
    and request_data >= #{begingDate} and request_data <= #{endDate} 
order by request_data desc,id desc limit #{pageIndex},#{pageSize}) as a
,b_marketing_transfer_sync_${tCid} as b
where a.id = b.id

select *
from b_marketing_transfer_sync_${tCid}
where api_code = #{apiCode} and request_data = #{requestDate}

    and id > #{minId}

order by id asc limit 2000;

select *
from b_marketing_transfer_sync_${tCid}
where api_code = #{apiCode} and request_data = #{requestDate}

    and id > #{minId}

order by id asc limit 2000;

select *
from b_marketing_transfer_sync_${tCid}
where api_code = #{apiCode}
   and register_time >= #{registerStartTime} and register_time < #{registerEndTime} 

    and id > #{minId}

order by id asc limit 2000;

select duplicate.*
from (select *, row_number() over (partition by cust_num order by insert_time desc ) as row_num
from b_marketing_transfer_sync_${tCid} a
where a.api_code = #{apiCode}
and a.request_data = #{requestDate}
) as duplicate
where duplicate.row_num = 1

    and duplicate.id > #{minId}

order by duplicate.id asc
limit 20000;

select * from (
select *,row_number() over(partition by cust_num order by create_time desc) as num
from b_marketing_transfer_sync_${tCid}
where
cust_num in

    #{c}

) t where num = 1

Select b.*
From (select a.id,a.cid,a.t_cid,a.api_code,a.request_id,a.org_name,a.cust_num,a.source,a.user_type,a.type,a.custom_name
,a.if_register,a.register_time,a.if_login,a.login_time,a.if_apply,a.apply_dt,a.apply_time,a.apply_result
,a.refuse_time,a.audit_time,a.audit_amount,a.if_lent,a.lent_time,a.lent_amount,a.unlent_amount,a.if_settle
,a.settle_time,a.activity,a.case_status,a.case_effective,a.if_transform,a.transform_time,a.insert_time
,a.request_time,a.request_data,a.reserve_field1,a.reserve_field2
,row_number() over (partition by cust_num order by insert_time desc,id desc) as rn
    From b_marketing_transfer_sync_${tCid} a
    where api_code =#{apiCode}
    and request_data = #{requestData}
    and (json_extract(reserve_field1,"$.transformType") !='1' or json_extract(reserve_field1,"$.transformType") is null)
   ) b
Where b.rn = 1

    and b.id > #{indexId}

  and b.type =#{type} order by b.id asc limit #{pageSize};

Select b.*
From (select a.id,a.cid,a.t_cid,a.api_code,a.request_id,a.org_name,a.cust_num,a.source,a.user_type,a.type,a.custom_name
    ,a.if_register,a.register_time,a.if_login,a.login_time,a.if_apply,a.apply_dt,a.apply_time,a.apply_result
    ,a.refuse_time,a.audit_time,a.audit_amount,a.if_lent,a.lent_time,a.lent_amount,a.unlent_amount,a.if_settle
    ,a.settle_time,a.activity,a.case_status,a.case_effective,a.if_transform,a.transform_time,a.insert_time
    ,a.request_time,a.request_data,a.reserve_field1,a.reserve_field2
    ,row_number() over(partition by cust_num order by insert_time desc,id desc) as rn
    From b_marketing_transfer_sync_${tCid} a
    where api_code =#{apiCode}
    and request_data = #{requestData}
    and (json_extract(reserve_field1,"$.transformType") !='1' or json_extract(reserve_field1,"$.transformType") is null)
   ) b
Where b.rn = 1

    and b.id > #{indexId}

  and json_extract(reserve_field1,"$.registerChannel") = #{registerChannel}
  and b.type =#{type} order by b.id asc limit #{pageSize};

select b.* from (select a.id,a.cid,a.t_cid,a.api_code,a.request_id,a.org_name,a.cust_num,a.source,a.user_type,a.type,a.custom_name ,a.if_register,a.register_time,a.if_login,a.login_time,a.if_apply,a.apply_dt,a.apply_time,a.apply_result ,a.refuse_time,a.audit_time,a.audit_amount,a.if_lent,a.lent_time,a.lent_amount,a.unlent_amount,a.if_settle ,a.settle_time,a.activity,a.case_status,a.case_effective,a.if_transform,a.transform_time,a.insert_time ,a.request_time,a.request_data,a.reserve_field1,a.reserve_field2 ,row_number() over (partition by cust_num order by create_time desc,id desc) as rn from b_marketing_transfer_sync_${tCid} a where request_data = #{requestDate} and api_code = #{apiCode} and json_extract(reserve_field1, '$.transformType') = '1' ) as b where b.rn = 1
and b.id > #{indexId}
and b.json_extract(reserve_field1, '$.liveType') in ('4', '6') order by b.id asc limit #{pageSize};

select b.*
From (select a.id,a.cid,a.t_cid,a.api_code,a.cust_num,a.reserve_field1 ,a.type,a.request_data,a.apply_result,a.apply_dt,
row_number() over(partition by cust_num order by insert_time desc,id desc) as rn
From b_marketing_transfer_sync_${tCid} a
where api_code =#{apiCode}
and request_data = #{requestDate}
and (json_extract(reserve_field1,"$.transformType") !='1' or json_extract(reserve_field1,"$.transformType") is null)
) b
where b.rn = 1

    and b.id > #{indexId}

and apply_result = '1' and apply_dt between #{applyDtStart} and #{applyDtEnd}
order by b.id asc limit #{pageSize};

select distinct cust_num
from b_marketing_transfer_sync_${cid}
where request_data = #{today}
  and api_code = #{apiCode}
  and (json_extract(reserve_field1, '$.transformType') != '1' or json_extract(reserve_field1,'$.transformType') is null)
  and type != '13'
  and cust_num in

    #{custNum}
  ;

select distinct cust_num
from b_marketing_transfer_sync_${cid}
where api_code = #{apiCode}
  and case_effective = '0'
  and cust_num in

    #{custNum}
  ;

select distinct tt1.cust_num,tt1.type from (
select t1.cust_num,t1.type,row_number() over(partition by cust_num,request_data order by insert_time desc) as rn
from b_marketing_transfer_sync_${cid} t1
where request_data between #{startDate} and #{endDate}
and (json_extract(reserve_field1, '$.transformType') != '1'
or json_extract(reserve_field1, '$.transformType') is null)
and api_code = #{apiCode}
and cust_num in

    #{custNum}

) tt1
where rn = 1
and tt1.type != '12'
and length(trim(tt1.type)) > 0
and tt1.type is not null;

select max(id)
from b_marketing_transfer_sync_${cid}
        where api_code = #{apiCode}
          and request_data = #{requestData}

    and type = #{type};

select count(1)
from b_marketing_transfer_sync_${cid}
where  request_id = #{requestId}

select *
from b_marketing_transfer_sync_${tCid}
where cust_num = #{custNum}
and (reserve_field1->'$.convType' = '106')
and api_code in

    #{apiCode}

limit 1

select *
from b_marketing_transfer_sync_${tCid}
where cust_num = #{custNum}
and (reserve_field1->'$.isBlack' = '1' or reserve_field1->'$.isBlack' = 1)
 and create_time < curdate()
and api_code in

    #{apiCode}

limit 1

select *
from b_marketing_transfer_sync_${tCid}
where cust_num = #{custNum}
and (reserve_field1->'$.isBlack' = '1' or reserve_field1->'$.isBlack' = 1)
 and create_time > curdate()
and api_code in

    #{apiCode}

limit 1

select id, cust_num, if_apply, if_lent
from b_marketing_transfer_sync_${tCid}
        where api_code = #{apiCode}
          and request_data = #{requestDate}
          and (if_apply = '1' or if_lent = '1')

    and id > #{indexId}

order by id limit 2000;

select id, cust_num, if_apply, if_lent
from b_marketing_transfer_sync_${tCid}
        where api_code = #{apiCode}
          and request_data = #{requestDate}
          and if_apply = '1'
            and apply_dt >= #{lastDateStart}
          and apply_dt <= #{lastDateEnd}


    and id > #{indexId}

order by id limit 2000;

select id, cust_num, if_apply, if_lent
from b_marketing_transfer_sync_${tCid}
        where api_code = #{apiCode}
          and request_data = #{requestDate}
          and if_lent = '1'
 and lent_time >= #{lastDateStart}
          and lent_time <= #{lastDateEnd}


    and id > #{indexId}

order by id limit 2000;

select

    distinct


from b_marketing_transfer_sync_${example.tCid} t2,(select id as t1_id from
b_marketing_transfer_sync_${example.tCid}




    ${sqlWhereClause}


    order by ${example.orderByClause}
) as t1 where t2.id= t1.t1_id;

select *
from b_marketing_transfer_sync_${tCid}
where
  register_time is not null and register_time <> '' and api_code = #{apiCode} and request_data >= #{requestStartDate} and request_data <= #{requestEndDate}

    and id > #{indexId}

order by id asc limit 1000

select *
from b_marketing_transfer_sync_${tCid}
where
 api_code = #{apiCode} and request_data >= #{requestStartDate} and request_data <= #{requestEndDate}

    and id > #{indexId}

order by id asc limit 1000

select count(1)
from b_marketing_transfer_sync_${cid}
where  cust_num = #{custNum}
and  (reserve_field1->'$.isBlack' = '1' or reserve_field1->'$.isBlack' = 1)

select count(1)
from b_marketing_transfer_sync_${cid}
where  cust_num = #{custNum}
and  if_apply = '1'
and request_data between #{dateStartStr} and #{dateEndStr}

select id,register_time,login_time
from b_marketing_transfer_sync_${cid}
where cust_num = #{custNum}
order by create_time desc limit 1

select *
from b_marketing_transfer_sync_${tCid}


        AND api_code =#{apiCode}


        and id > #{indexId}


        and  request_data >= #{requestStartDate} and request_data <= #{requestEndDate}

    and ${querySql}
    order by id asc limit 2000;

select *
from b_marketing_transfer_sync_${tCid}


        AND api_code =#{apiCode}


        and  request_data >= #{requestStartDate} and request_data <= #{requestEndDate}


        and cust_num in

            #{item}


    and ${querySql}

select cust_num,
       if(sum(if(reserve_field1 -> '$.convType' = '110', 1, 0)) > 0, true, false) as hasRiskControl,
       if(sum(if(reserve_field1 -> '$.convType' = '106', 1, 0)) > 0, true, false) as hasApplySuccess,
       if(sum(if(reserve_field1 -> '$.convType' = '107', 1, 0)) > 0, true, false) as hasInputSuccess
from b_marketing_transfer_sync_${tCid}
        where api_code in

    #{apiCode}


and request_data >= #{requestStartDate}
and request_data <= #{requestEndDate}
and cust_num in

    #{item}

group by cust_num;

select id, cust_num, login_time, apply_dt, request_data
from b_marketing_transfer_sync_${tCid}
        where api_code = #{apiCode}
          and (json_extract(reserve_field1, "$.transformType") !='1' or json_extract(reserve_field1,"$.transformType") is null)

          and request_data >= #{requestStartDate}
          and request_data <= #{requestEndDate}


    and id > #{indexId}

